-- =====================================================================
-- SAMPLE27 - integrity and date-range checks
-- Copyright (c) 2026 Marcin Paluch. All rights reserved.
-- Every "chk" row must be 0 except: 'EMPLOYEE JOB longer than 3 chars'
-- (informational) and 'ACT row count' (expected 18).
-- =====================================================================

CONNECT TO SAMPLE27;

SELECT 'EMPPROJACT orphan EMPNO' AS chk, COUNT(*) AS n FROM DB2INST1.EMPPROJACT e WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.EMPLOYEE x WHERE x.EMPNO=e.EMPNO)
UNION ALL SELECT 'EMPPROJACT null EMSTDATE', COUNT(*) FROM DB2INST1.EMPPROJACT WHERE EMSTDATE IS NULL
UNION ALL SELECT 'EMPPROJACT dup (EMPNO,PROJNO,ACTNO,EMSTDATE)', COUNT(*) FROM (SELECT 1 FROM DB2INST1.EMPPROJACT GROUP BY EMPNO,PROJNO,ACTNO,EMSTDATE HAVING COUNT(*)>1)
UNION ALL SELECT 'EMPPROJACT orphan PROJACT', COUNT(*) FROM DB2INST1.EMPPROJACT e WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.PROJACT p WHERE p.PROJNO=e.PROJNO AND p.ACTNO=e.ACTNO AND p.ACSTDATE=e.EMSTDATE)
UNION ALL SELECT 'INVENTORY orphan PID', COUNT(*) FROM DB2INST1.INVENTORY i WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.PRODUCT p WHERE p.PID=i.PID)
UNION ALL SELECT 'PRODUCTSUPPLIER orphan PID', COUNT(*) FROM DB2INST1.PRODUCTSUPPLIER s WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.PRODUCT p WHERE p.PID=s.PID)
UNION ALL SELECT 'PRODUCTSUPPLIER orphan SID', COUNT(*) FROM DB2INST1.PRODUCTSUPPLIER s WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.SUPPLIERS x WHERE x.SID=s.SID)
UNION ALL SELECT 'STAFF dup ID', COUNT(*) FROM (SELECT 1 FROM DB2INST1.STAFF GROUP BY ID HAVING COUNT(*)>1)
UNION ALL SELECT 'ORG dup DEPTNUMB', COUNT(*) FROM (SELECT 1 FROM DB2INST1.ORG GROUP BY DEPTNUMB HAVING COUNT(*)>1)
UNION ALL SELECT 'PATIENTS dup/null PATIENT_ID', COUNT(*) FROM (SELECT 1 FROM DB2INST1.PATIENTS GROUP BY PATIENT_ID HAVING COUNT(*)>1 OR PATIENT_ID IS NULL)
UNION ALL SELECT 'PROJACT bad date range', COUNT(*) FROM DB2INST1.PROJACT WHERE ACENDATE < ACSTDATE
UNION ALL SELECT 'EMPPROJACT bad date range', COUNT(*) FROM DB2INST1.EMPPROJACT WHERE EMENDATE < EMSTDATE
UNION ALL SELECT 'PROJECT bad date range', COUNT(*) FROM DB2INST1.PROJECT WHERE PRENDATE < PRSTDATE
UNION ALL SELECT 'PRODUCT bad promo range', COUNT(*) FROM DB2INST1.PRODUCT WHERE PROMOEND < PROMOSTART
UNION ALL SELECT 'EMPLOYEE hired before age 18', COUNT(*) FROM DB2INST1.EMPLOYEE WHERE HIREDATE < BIRTHDATE + 18 YEARS
UNION ALL SELECT 'EMPLOYEE has project activity before the hire date', COUNT(*) FROM DB2INST1.EMPLOYEE e WHERE e.HIREDATE > (SELECT MIN(p.EMSTDATE) FROM DB2INST1.EMPPROJACT p WHERE p.EMPNO=e.EMPNO)
UNION ALL SELECT 'PURCHASEORDER PoNum in XML differs from POID', COUNT(*) FROM DB2INST1.PURCHASEORDER WHERE POID <> XMLCAST(XMLQUERY('$p/PurchaseOrder/@PoNum' PASSING PORDER AS "p") AS BIGINT)
UNION ALL SELECT 'PURCHASEORDER item partid not in PRODUCT', COUNT(*) FROM DB2INST1.PURCHASEORDER O, XMLTABLE('$p/PurchaseOrder/item' PASSING O.PORDER AS "p" COLUMNS PARTID VARCHAR(10) PATH 'partid') X WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.PRODUCT P WHERE P.PID = X.PARTID)
UNION ALL SELECT 'PRODUCT without INVENTORY row', COUNT(*) FROM DB2INST1.PRODUCT P WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.INVENTORY I WHERE I.PID = P.PID)
UNION ALL SELECT 'EMPPROJACT outside project date range', COUNT(*) FROM DB2INST1.EMPPROJACT e JOIN DB2INST1.PROJECT p ON p.PROJNO=e.PROJNO WHERE e.EMSTDATE < p.PRSTDATE OR e.EMSTDATE > p.PRENDATE OR e.EMENDATE > p.PRENDATE
UNION ALL SELECT 'PROJACT outside project date range', COUNT(*) FROM DB2INST1.PROJACT a JOIN DB2INST1.PROJECT p ON p.PROJNO=a.PROJNO WHERE a.ACSTDATE < p.PRSTDATE OR a.ACSTDATE > p.PRENDATE OR a.ACENDATE > p.PRENDATE
UNION ALL SELECT 'sub-project outside parent project date range', COUNT(*) FROM DB2INST1.PROJECT c JOIN DB2INST1.PROJECT p ON p.PROJNO=c.MAJPROJ WHERE c.PRSTDATE < p.PRSTDATE OR c.PRENDATE > p.PRENDATE

UNION ALL SELECT 'EMPLOYEE JOB longer than 3 chars', COUNT(*) FROM DB2INST1.EMPLOYEE WHERE LENGTH(RTRIM(JOB))>3
UNION ALL SELECT 'DEPARTMENT.ADMRDEPT orphan', COUNT(*) FROM DB2INST1.DEPARTMENT d WHERE NOT EXISTS (SELECT 1 FROM DB2INST1.DEPARTMENT x WHERE x.DEPTNO=d.ADMRDEPT)
UNION ALL SELECT 'ACT row count', COUNT(*) FROM DB2INST1.ACT;

SELECT 'HIREDATE' AS col, MIN(HIREDATE) AS mn, MAX(HIREDATE) AS mx FROM DB2INST1.EMPLOYEE
UNION ALL SELECT 'BIRTHDATE', MIN(BIRTHDATE), MAX(BIRTHDATE) FROM DB2INST1.EMPLOYEE
UNION ALL SELECT 'ORDERDATE', MIN(ORDERDATE), MAX(ORDERDATE) FROM DB2INST1.PURCHASEORDER
UNION ALL SELECT 'SALES_DATE', MIN(SALES_DATE), MAX(SALES_DATE) FROM DB2INST1.SALES
UNION ALL SELECT 'PRSTDATE', MIN(PRSTDATE), MAX(PRSTDATE) FROM DB2INST1.PROJECT
UNION ALL SELECT 'PRENDATE', MIN(PRENDATE), MAX(PRENDATE) FROM DB2INST1.PROJECT
UNION ALL SELECT 'ACSTDATE', MIN(ACSTDATE), MAX(ACSTDATE) FROM DB2INST1.PROJACT
UNION ALL SELECT 'ACENDATE', MIN(ACENDATE), MAX(ACENDATE) FROM DB2INST1.PROJACT
UNION ALL SELECT 'EMSTDATE', MIN(EMSTDATE), MAX(EMSTDATE) FROM DB2INST1.EMPPROJACT
UNION ALL SELECT 'EMENDATE', MIN(EMENDATE), MAX(EMENDATE) FROM DB2INST1.EMPPROJACT
UNION ALL SELECT 'PROMOSTART', MIN(PROMOSTART), MAX(PROMOSTART) FROM DB2INST1.PRODUCT
UNION ALL SELECT 'PROMOEND', MIN(PROMOEND), MAX(PROMOEND) FROM DB2INST1.PRODUCT;

CONNECT RESET;
